// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testRegression_property() public {
        c.SetMinSum(0);
        Log logFile = new Log();
        c.SetLogFile(address(logFile));
        c.Initialized();

        address alice = address(0x1234);
        vm.deal(alice, 1);
        vm.prank(alice);
        c.Put{value: 1}(0);

        bool ok;
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Collect should succeed in reference");
    }
}

contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
